import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"渙","description":"焦氏易林注 - 渙","frontmatter":{"title":"渙","description":"焦氏易林注 - 渙"},"headers":[],"relativePath":"zh/classics/jiaoyilin/059.md","filePath":"zh/classics/jiaoyilin/059.md"}'),l={name:"zh/classics/jiaoyilin/059.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="渙" tabindex="-1">渙 <a class="header-anchor" href="#渙" aria-label="Permalink to “渙”">​</a></h1><h3 id="渙-1" tabindex="-1">渙 <a class="header-anchor" href="#渙-1" aria-label="Permalink to “渙”">​</a></h3><h3 id="渙之乾" tabindex="-1">渙之乾 <a class="header-anchor" href="#渙之乾" aria-label="Permalink to “渙之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>猋風阻越，車馳揭揭。棄古追思，失其和節，憂心惙惙。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>詳《需》之《小過》。第三句汲古作棄名追亡，元本作棄古退思，茲依宋本。又揭揭，汲古訛竭竭，依宋元本。</p><h3 id="渙之坤" tabindex="-1">渙之坤 <a class="header-anchor" href="#渙之坤" aria-label="Permalink to “渙之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>蛇得澤草，不憂危殆。此用渙象。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>巽為蛇，震為草，草在坎中，故曰澤草。坎為危殆，震解，故不危。</p><h3 id="渙之屯" tabindex="-1">渙之屯 <a class="header-anchor" href="#渙之屯" aria-label="Permalink to “渙之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>兩犬爭鬬，股瘡無處。不成仇讎，行解卻去。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>互艮為犬，正反艮，故曰兩犬爭鬥。艮為節、為瘡，巽為股，巽伏，故曰股瘡無處。坎為仇，巽為隙，震解，巽伏，故曰不仇、曰解隙。○卻，同隙，宋元本作邪，汲古作卻，依局本。</p><h3 id="渙之蒙" tabindex="-1">渙之蒙 <a class="header-anchor" href="#渙之蒙" aria-label="Permalink to “渙之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>因禍受福，喜盈其室，求事皆得。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>坤為禍，震為福喜，艮為室，坤多，故曰喜盈其室。</p><h3 id="渙之需" tabindex="-1">渙之需 <a class="header-anchor" href="#渙之需" aria-label="Permalink to “渙之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>江有寶珠，海多大魚。亟行疾去，可以得財。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>乾為江河、為玉，故曰寶珠。伏坤為海、為魚、為疾、為財。○有，宋元本作多，亟疾作疾亟，依汲古。</p><h3 id="渙之訟" tabindex="-1">渙之訟 <a class="header-anchor" href="#渙之訟" aria-label="Permalink to “渙之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>三牛生狗，以戌為母。荊夷上侵，姬伯出走。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《震》。三牛，宋元本作三年，依汲古。</p><h3 id="渙之師" tabindex="-1">渙之師 <a class="header-anchor" href="#渙之師" aria-label="Permalink to “渙之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>安息康居，異國穹廬。非君習俗，使伯憂惑。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《比》。末句宋元本作使伯心憂，茲依汲古。惑與俗韻，憂不協。</p><h3 id="渙之比" tabindex="-1">渙之比 <a class="header-anchor" href="#渙之比" aria-label="Permalink to “渙之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>行觸天罡，馬死車傷。身無聊賴，困窮乏糧。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>《參同契》二月榆魁臨於卯，麥生，天罡據西。註：天罡，即北斗。睽之漸曰：魁罡所當，初為敗殃，是天罡所指之處亡也。艮為星，故曰天罡。艮卦數七，北斗七星，象尤切也。坤為車馬、為死傷、為身、為窮乏，震為糧，震覆，故曰乏糧。○罡，汲古訛綱，局本又訛網，依宋元本。</p><h3 id="渙之小畜" tabindex="-1">渙之小畜 <a class="header-anchor" href="#渙之小畜" aria-label="Permalink to “渙之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>裸裎逐狐，為人觀笑。牝雞司晨，主母亂門。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《咸》。母，元本作作，非。</p><h3 id="渙之履" tabindex="-1">渙之履 <a class="header-anchor" href="#渙之履" aria-label="Permalink to “渙之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>為季求婦，家在東海。水長無船，不見所歡。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>詳《屯》之《蹇》。</p><h3 id="渙之泰" tabindex="-1">渙之泰 <a class="header-anchor" href="#渙之泰" aria-label="Permalink to “渙之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>男女合室，二姓同食。婚姻孔雲，宜我多孫。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>乾男坤女，伏艮為室，乾坤交，故曰合室。坤為姓，兌為食，兌卦數二，故曰二姓同食。震為嫁，故曰婚姻。伏艮為孫。○末句元本作宜室我家，茲依宋本、汲古。</p><h3 id="渙之否" tabindex="-1">渙之否 <a class="header-anchor" href="#渙之否" aria-label="Permalink to “渙之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>太微帝室，黃帝所直。藩屏周衛，不可得入。常安長在，終無禍患。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>太微，即紫微。《史記天官書》中宮天極星，其一明者，太一常居也。註雲：紫微大帝室，太微帝室者，言紫微垣為天帝之中宮也。《天官書》又雲：填星中央土，主季夏日戊己，黃帝主德。茲曰黃帝所直。黃帝，即軒轅星，言黃帝直中宮。中宮，即中央。藩屏周衛者，《天官書》太一旁三星三公，後句四星未大星正妃餘三星後宮之屬環之，匡衛十二星藩臣皆曰紫宮，言各星藩衛太微，周環紫宮，故曰不可入也。否互艮為星，而與乾連，乾為帝，艮為室，故曰帝室。坤為黃、為直，故曰黃帝所直。艮為屏藩、為衛，艮堅，故不得入。○長在，宋元本作常存，茲依汲古。</p><h3 id="渙之同人" tabindex="-1">渙之同人 <a class="header-anchor" href="#渙之同人" aria-label="Permalink to “渙之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>齎金觀市，欲買騮子。猾偷竊發，盜我黃寶。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>乾為金，互巽為市，下離，故曰觀市。乾為馬，伏震為子，故曰騮子。巽為盜、為偷竊，離為黃，乾為金玉，故曰黃寶。</p><h3 id="渙之大有" tabindex="-1">渙之大有 <a class="header-anchor" href="#渙之大有" aria-label="Permalink to “渙之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>三人俱行，欲歸故鄉。望邑入門，拜見家親。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>此用渙象。震為人，數三，故曰三人。震為行、為歸，艮為鄉邑、為門、為拜、為家、為觀，故曰望。○人，汲古作思，依宋元本。親，宋元本作歡，依汲古。</p><h3 id="渙之謙" tabindex="-1">渙之謙 <a class="header-anchor" href="#渙之謙" aria-label="Permalink to “渙之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>娶於薑呂，駕迎新婦。少齊在門，夫子悅喜。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《渙》。</p><h3 id="渙之豫" tabindex="-1">渙之豫 <a class="header-anchor" href="#渙之豫" aria-label="Permalink to “渙之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>伯仲旅行，南求大牂。長孟病足，倩季負糧。柳下之寶，不失我邦。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為伯，坎為仲、為眾，故曰旅行。旅，眾也。震為南，艮為求，伏兌為羊，故曰大牂。震為長、為孟、為足，互坎，故曰病足。《家語》叔梁紇施氏生九女，其妾生孟皮，孟皮病足。長孟即謂孟皮也。艮為季、為負，伏巽為糧，故曰負糧。季，季路也。《家語》子路為親負米百裡之外。震為柳，坤下，故曰柳下。艮為邦。事詳《同人》之《豐》。○長孟，汲古作孟長，依宋元本。寶，各本皆作貞，依《同人》之《豐》校。我邦，宋元本作驪黃。獨汲古存其真，於事實皆切。糧，各本皆作囊，獨汲古《革》之《恆》作糧，故依校。</p><h3 id="渙之隨" tabindex="-1">渙之隨 <a class="header-anchor" href="#渙之隨" aria-label="Permalink to “渙之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>潔身白齒，衰老復起。多孫眾子，宜利姑舅。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>艮為身，兌為齒，巽白，故曰潔身白齒。艮為壽，故曰衰老。下卦艮覆為震，故曰衰老復起。艮為孫，震為子，巽為姑，震為舅。</p><h3 id="渙之蠱" tabindex="-1">渙之蠱 <a class="header-anchor" href="#渙之蠱" aria-label="Permalink to “渙之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>獨宿憎夜，嫫母畏晝。平王逐建，荊子憂懼。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>巽為寡，巽伏，故曰獨宿。互大坎為夜、為憎，巽為母，兌魯，故曰嫫母。互大離，故曰畏晝。坎為平，震為王、為逐、為建，言楚平王逐太子建也。震為子、為草莽，故曰荊子。○憎，與下畏對文，汲古作深，雖與大坎象切，於文終不適，故依宋元本。獨宿無耦，故憎夜長；嫫母貌醜，故畏晝見。</p><h3 id="渙之臨" tabindex="-1">渙之臨 <a class="header-anchor" href="#渙之臨" aria-label="Permalink to “渙之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>追亡逐北，至山而得。稚叔相呼，反其室廬。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>依《需》之《渙》校。各本下三句皆作呼還幼叔，至山而得，復歸其室。</p><h3 id="渙之觀" tabindex="-1">渙之觀 <a class="header-anchor" href="#渙之觀" aria-label="Permalink to “渙之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>鳥飛無翼，兔走折足。雖欲會同，未見其功。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>震為翼、為足、為兔，震覆，故無翼，故折足。艮為鳥。由此證《明夷》初爻之垂其翼，以六四震為翼，諸家以離為翼，皆非。○見其，宋元本作得醫，茲依汲古。</p><h3 id="渙之噬嗑" tabindex="-1">渙之噬嗑 <a class="header-anchor" href="#渙之噬嗑" aria-label="Permalink to “渙之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>抱空握虗，鴞驚我雛，利去不來。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>詳《離》之《家人》。去來，汲古作出成，依宋元本。</p><h3 id="渙之賁" tabindex="-1">渙之賁 <a class="header-anchor" href="#渙之賁" aria-label="Permalink to “渙之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>山作大池，陸地為海。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>艮為山、為陸地，坎為池、為海，汲古多各得其所四字，宋元本無。大，宋元本作天，依汲古。</p><h3 id="渙之剝" tabindex="-1">渙之剝 <a class="header-anchor" href="#渙之剝" aria-label="Permalink to “渙之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>為虎所嚙，泰山之陽。眾多從者，莫敢救藏。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>艮為虎，伏兌為嚙，艮為山，納丙，故曰山陽。坤為眾多，丁雲事見檀弓。按：檀弓記孔子過泰山，謂苛政猛於虎，於此亦不甚合。</p><h3 id="渙之復" tabindex="-1">渙之復 <a class="header-anchor" href="#渙之復" aria-label="Permalink to “渙之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>逶迤四牡，思歸念母。王事靡盬，不得安處。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>詳《旅》之《漸》。</p><h3 id="渙之無妄" tabindex="-1">渙之無妄 <a class="header-anchor" href="#渙之無妄" aria-label="Permalink to “渙之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>獮猴所言，語無成全。誤我白馬，使乾口來。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>艮為獮猴，震言，乾馬，巽色白，故曰白馬。震為口，艮火，故曰乾口。</p><h3 id="渙之大畜" tabindex="-1">渙之大畜 <a class="header-anchor" href="#渙之大畜" aria-label="Permalink to “渙之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>飛不遠去，卑斯內侍，祿養豐富。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>詳《豐》之《渙》。斯，汲古作廝，非。</p><h3 id="渙之頤" tabindex="-1">渙之頤 <a class="header-anchor" href="#渙之頤" aria-label="Permalink to “渙之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>大尾細要，重不可搖。陰權制國，平子逐昭。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為尾，震為大，故曰大尾。坎為腰，今中爻皆陰，故曰細腰。《莊子》細要者化。謂蜂也。坤為重，震為搖，艮止，故不可搖。坤為國，伏巽為權，故曰陰權制國。坤為平，震為子、為逐，震為光明，故曰平子逐昭。○要，汲古作，非，依宋元本。西漢時多作要，故知要為本字，是後人所改。</p><h3 id="渙之大過" tabindex="-1">渙之大過 <a class="header-anchor" href="#渙之大過" aria-label="Permalink to “渙之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>旦生夕死，名曰嬰鬼，不可得祀。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《升》。祀，宋元本訛視，依汲古。</p><h3 id="渙之坎" tabindex="-1">渙之坎 <a class="header-anchor" href="#渙之坎" aria-label="Permalink to “渙之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>子畏於匡，困於陳蔡。明德不危，竟免厄害。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>坎為畏，艮邑，故曰匡。坎為困，震為陳、為蔡、為德，艮為光明，故曰明德。坎為困厄，震解，故曰危。○厄，元本作危，非，依汲古。</p><h3 id="渙之離" tabindex="-1">渙之離 <a class="header-anchor" href="#渙之離" aria-label="Permalink to “渙之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>畏昏潛處，候時昭朗。卒逢白日，為世榮主。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>詳前。昭朗，元本作朗昭，依汲古。</p><h3 id="渙之咸" tabindex="-1">渙之咸 <a class="header-anchor" href="#渙之咸" aria-label="Permalink to “渙之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>白鳥銜鉺，鳴呼其子。旋枝張翅，來從其母。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《晉》之《震》。旋枝，宋元本作旋翼，依汲古。</p><h3 id="渙之恒" tabindex="-1">渙之恒 <a class="header-anchor" href="#渙之恒" aria-label="Permalink to “渙之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>宮商角徵，五音和起。君臣父子，弟順有序。唐虞龍德，國無災咎。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>伏坤，故曰宮。兌秋，故曰商。巽居巳，故屬夏。樂書徵配夏，《月令》孟春之月，其音角，故震為角。宮商角徵，皆卦象也。震為音，巽卦數五，故曰五音。震為君，伏艮為臣，乾父震子，故曰君臣父子。巽順，故曰悌。震為帝，故曰唐虞。伏坤為國。</p><h3 id="渙之遯" tabindex="-1">渙之遯 <a class="header-anchor" href="#渙之遯" aria-label="Permalink to “渙之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>季姬踟躕，望孟城隅。終日至暮，不見齊候。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《隨》。</p><h3 id="渙之大壯" tabindex="-1">渙之大壯 <a class="header-anchor" href="#渙之大壯" aria-label="Permalink to “渙之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>鬼哭於社，悲商無後。甲子昧爽，殷人絕祀。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>詳《大過》之《坤》。</p><h3 id="渙之晉" tabindex="-1">渙之晉 <a class="header-anchor" href="#渙之晉" aria-label="Permalink to “渙之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>天之所予，福祿常在，不憂危殆。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>詳《小畜》之《遯》。之，宋元本作子，依汲古。</p><h3 id="渙之明夷" tabindex="-1">渙之明夷 <a class="header-anchor" href="#渙之明夷" aria-label="Permalink to “渙之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>比目四翼，相恃為福。薑氏季女，與君合德。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>離為目，坤偶，故曰比目。震為翼，卦數四，故曰四翼、為福。伏巽為薑，坎為合，震為君、為德，《左傳桓九年》紀季薑歸於京師，為桓王后。</p><h3 id="渙之家人" tabindex="-1">渙之家人 <a class="header-anchor" href="#渙之家人" aria-label="Permalink to “渙之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>翕翕，稍崩墮顛。滅其令名，長沒不全。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《謙》。</p><h3 id="渙之睽" tabindex="-1">渙之睽 <a class="header-anchor" href="#渙之睽" aria-label="Permalink to “渙之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>折若蔽目，不見稚叔。三足孤烏，遠去家室。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《蒙》。若，汲古作葉，稚作雉，孤烏作飛鳥，均依宋元本。此用渙象。</p><h3 id="渙之蹇" tabindex="-1">渙之蹇 <a class="header-anchor" href="#渙之蹇" aria-label="Permalink to “渙之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>羊腸九縈，相推稍前。止須王孫，乃能上天。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《履》之《師》。</p><h3 id="渙之解" tabindex="-1">渙之解 <a class="header-anchor" href="#渙之解" aria-label="Permalink to “渙之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>坤厚地德，蔗物蕃息。平康正直，以綏大福。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《解》。</p><h3 id="渙之損" tabindex="-1">渙之損 <a class="header-anchor" href="#渙之損" aria-label="Permalink to “渙之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>有莘外野，不逢堯主。復歸窮處，心勞志苦。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>震為莘。莘，草名也。坤為野，震為主、為帝，故曰堯主。震為歸，坤為心志、為勞苦。鯀取有莘氏女，本在野之人，後堯用以治水。倘鯀不逢堯，則窮老於有莘之野耳。○歸，宋元本作居，依汲古。</p><h3 id="渙之益" tabindex="-1">渙之益 <a class="header-anchor" href="#渙之益" aria-label="Permalink to “渙之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>咠長景行，來觀柘桑。土伯有喜，都叔允藏。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>咠為邑之訛字，《禮檀弓》以吾為邑長於斯也。震為長、為行、為柘桑，艮為觀，故曰來觀柘桑，言邑長出巡也。震為伯，互坤，故曰土伯。土伯，即周禮地官之土訓，土訓掌辨地物而原其生。震樂，故曰有喜。坤為都，艮為叔，故曰都叔。都叔，蓋都士都則之屬。○咠，音緝。篆書作●，而邑篆作●，形近，故邑訛為咠。宋元本作胷，依汲古。士，宋元本作上，汲古作止，依局本。</p><h3 id="渙之夬" tabindex="-1">渙之夬 <a class="header-anchor" href="#渙之夬" aria-label="Permalink to “渙之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>周師伐紂，戰於牧野。甲子平旦，天下大喜。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《噬嗑》。戰，宋元本作勝，依汲古。大，依宋元本，汲古作喜悅。</p><h3 id="渙之姤" tabindex="-1">渙之姤 <a class="header-anchor" href="#渙之姤" aria-label="Permalink to “渙之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>逾江求橘，並得大慄。烹羊食豕，飲酒歌笑。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>乾為木果，故曰橘、曰慄。乾為河、為江、為大，故曰大慄。伏震為羊，巽為豕，震為歌笑。○豕，宋元本作炙，依汲古。酒，汲古作食，依宋元本。</p><h3 id="渙之萃" tabindex="-1">渙之萃 <a class="header-anchor" href="#渙之萃" aria-label="Permalink to “渙之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>敝笱在梁，魴逸不禁。漁父勞苦，焦喉乾口，虛空無有。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>第四句宋元本作筐筥乾口，汲古作口焦喉乾，茲依《遯》之《大過》校。</p><h3 id="渙之升" tabindex="-1">渙之升 <a class="header-anchor" href="#渙之升" aria-label="Permalink to “渙之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>生有陰孽，制家非陽。逐送還床，張氏易公。憂禍重凶。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>送，汲古作受，床作作，公作休，均依宋元本。禍，元本作福，依宋本、汲古。然仍有訛字，故義皆不能通。</p><h3 id="渙之困" tabindex="-1">渙之困 <a class="header-anchor" href="#渙之困" aria-label="Permalink to “渙之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>絕域異路，多有畏惡。使我驚懼，思吾故處。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>詳《漸》之《無妄》。思吾，依校，各本皆作思我。</p><h3 id="渙之井" tabindex="-1">渙之井 <a class="header-anchor" href="#渙之井" aria-label="Permalink to “渙之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>迷行失道，不得牛馬。百賈逃亡，市空無有。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>坎為失、為隱伏，故曰迷行失道。伏震為行、為道也。艮為牛，震為馬，艮震伏，故不得。巽為市賈，離虛，故曰空。○牛馬，汲古作馬牛，依宋元本。</p><h3 id="渙之革" tabindex="-1">渙之革 <a class="header-anchor" href="#渙之革" aria-label="Permalink to “渙之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>雌鷟生雛，神異興起。乘雲龍騰，民戴為父。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>通《蒙》。艮為鷟，震為生、為雛、為神、為起。坤為雲，震為龍、為乘、為騰、為父，坤為民，艮為戴。○鷟，宋本、汲古皆作鸑，茲依元本。乘，宋元本訛束，依汲古。</p><h3 id="渙之鼎" tabindex="-1">渙之鼎 <a class="header-anchor" href="#渙之鼎" aria-label="Permalink to “渙之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>疊疊纍纍，如岐之室。畜一息十，古公治邑。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《恆》之《小過》。○疊，宋元本作壘，治作始，均依汲古。</p><h3 id="渙之震" tabindex="-1">渙之震 <a class="header-anchor" href="#渙之震" aria-label="Permalink to “渙之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>瘡瘍疥瘙，孝婦不省。君多疣贅，四牧作去。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>互艮多節，故曰瘡瘍疥瘙。瘙，亦瘡也。巽為婦，巽順，故曰孝婦。巽伏，故曰不省。艮為疣贅，震君，故曰君多疣贅。震為馬，卦數四，故曰四牧。震往，故曰去。○瘙，宋元本作搔，非，依汲古。牧去，汲古作時災，不協，依宋元本。</p><h3 id="渙之艮" tabindex="-1">渙之艮 <a class="header-anchor" href="#渙之艮" aria-label="Permalink to “渙之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>羊頭兔足，羸瘦少肉。漏囊敗慄，利無所得。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《恆》。</p><h3 id="渙之漸" tabindex="-1">渙之漸 <a class="header-anchor" href="#渙之漸" aria-label="Permalink to “渙之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>孽蔑徙靡，空無誰是。言季不明，樂減少解。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>字既多訛，義都未解。孽徒，宋元本作孽從，不作子，亦未知孰是。</p><h3 id="渙之歸妹" tabindex="-1">渙之歸妹 <a class="header-anchor" href="#渙之歸妹" aria-label="Permalink to “渙之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>妹為貌慹，敗君正色。作事不成，自為心賊。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>震為嫁，兌為妹。伏艮為須，以女而有須，故曰貌慹。《莊子田子方》老聃新沐，被髮而乾慹，然似非人。慹，音懾，言可怖也。坎為畏懼，故曰慹。震為君，兌毀，故曰敗、曰不成。艮為成，艮伏，故不成。坎為心、為賊。○慹，宋元本、汲古均作熟，局本作熱，蓋由慹訛為熱，又由熱訛熟，茲依局本。又為貌汲古作貌親，是又因熟字而妄改，局本熱字即是慹字，而微異耳。</p><h3 id="渙之豐" tabindex="-1">渙之豐 <a class="header-anchor" href="#渙之豐" aria-label="Permalink to “渙之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>四馬共轅，東上太山。騂驪同力，無有重難，與君笑言。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>詳《剝》之《解》。</p><h3 id="渙之旅" tabindex="-1">渙之旅 <a class="header-anchor" href="#渙之旅" aria-label="Permalink to “渙之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>陰變為陽，女化作男。治道得通，君臣相承。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《離》。渙之旅中四爻艮為兌，震為巽，亦巽為震，故曰女化男。《左傳》震之離，亦離之震是其例也。君臣相承者，言陽為君，陰為臣，卦形上一陰承一陽，下二陰承二陽也。○作，汲古作為，依宋元本。</p><h3 id="渙之巽" tabindex="-1">渙之巽 <a class="header-anchor" href="#渙之巽" aria-label="Permalink to “渙之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>南國少子，材略美好。求我長女，賤薄不與。反得醜惡，後乃大悔。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>詳《比》之《漸》。</p><h3 id="渙之兌" tabindex="-1">渙之兌 <a class="header-anchor" href="#渙之兌" aria-label="Permalink to “渙之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>昭公失常，季氏悖狂。遜齊處野，喪其寵光。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>詳《遯》之《蠱》。</p><h3 id="渙之渙" tabindex="-1">渙之渙 <a class="header-anchor" href="#渙之渙" aria-label="Permalink to “渙之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>望幸不到，文章未就。王子逐兔，犬踦不得。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《既濟》。王，汲古作羊，非，依元本。</p><h3 id="渙之節" tabindex="-1">渙之節 <a class="header-anchor" href="#渙之節" aria-label="Permalink to “渙之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>文山紫芝，雍梁朱草。生長和氣，王以為寶。公屍侑食，福祿來處。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>詳《同人》之《剝》。</p><h3 id="渙之中孚" tabindex="-1">渙之中孚 <a class="header-anchor" href="#渙之中孚" aria-label="Permalink to “渙之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>牽羊不前，與心戾旋。聞言不信，誤紿丈人。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>兌羊，艮手，故曰牽羊。艮止，故曰不前。兌為耳，中爻正反震，故曰聞言不信、曰誤紿丈人。震為丈人。</p><h3 id="渙之小過" tabindex="-1">渙之小過 <a class="header-anchor" href="#渙之小過" aria-label="Permalink to “渙之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>東山西山，各自止安。心雖相望，竟未同堂。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>詳《姤》之《坤》。艮為望、為堂，正反艮，故曰相望、曰未同堂。</p><h3 id="渙之既濟" tabindex="-1">渙之既濟 <a class="header-anchor" href="#渙之既濟" aria-label="Permalink to “渙之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>鹿求其子，虎廬之里。唐伯李耳，貪不我許。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>詳《隨》之《否》。</p><h3 id="渙之未濟" tabindex="-1">渙之未濟 <a class="header-anchor" href="#渙之未濟" aria-label="Permalink to “渙之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>三虎上山，更相喧喚。心志不親，如仇與怨。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>詳《姤》之《小過》。首二句用半象。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
